using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side in-memory implementation of IShipmentService.
/// Replace with EF Core DbContext-backed implementation for production.
/// </summary>
public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> Shipments = new()
    {
        new() { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, CreatedAt = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new() { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.PickedUp, CreatedAt = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(7), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new() { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.OutForDelivery, CreatedAt = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "carol@example.com", Description = "Auto parts - 5 boxes" },
        new() { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "São Paulo, BR", Destination = "Miami, US", Status = ShipmentStatus.Delivered, CreatedAt = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "alice@example.com", Description = "Textiles - 3 cartons" },
        new() { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "Mumbai, IN", Destination = "Sydney, AU", Status = ShipmentStatus.Delayed, CreatedAt = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "dave@example.com", Description = "Pharmaceuticals - temperature controlled" },
    };

    private static int _nextId = 6;
    private static readonly Lock Lock = new();

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (Lock) { return Task.FromResult(Shipments.ToList()); }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (Lock)
        {
            var shipment = Shipments.FirstOrDefault(s =>
                s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string customerEmail)
    {
        lock (Lock)
        {
            var results = Shipments
                .Where(s => s.CustomerEmail.Equals(customerEmail, StringComparison.OrdinalIgnoreCase))
                .ToList();
            return Task.FromResult(results);
        }
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        lock (Lock)
        {
            var shipment = Shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
                shipment.Status = newStatus;
        }
        return Task.CompletedTask;
    }

    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        lock (Lock)
        {
            shipment.Id = _nextId++;
            shipment.CreatedAt = DateTime.UtcNow;
            Shipments.Add(shipment);
            return Task.FromResult(shipment);
        }
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        }).AllowAnonymous();

        group.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
            Results.Ok(await service.GetShipmentsForCustomerAsync(email)));

        group.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, IShipmentService service) =>
        {
            await service.UpdateShipmentStatusAsync(id, newStatus);
            return Results.NoContent();
        });

        group.MapPost("/", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        });
    }
}

