@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>

<p>Welcome to the logistics shipment tracking system.</p>

<AuthorizeView>
    <Authorized>
        <p>You are signed in as <strong>@context.User.Identity?.Name</strong>.</p>
        <ul>
            <li><a href="dispatch">Dispatcher Dashboard</a> — View and manage all shipments</li>
            <li><a href="my-shipments">My Shipments</a> — View your shipments and delivery estimates</li>
        </ul>
    </Authorized>
    <NotAuthorized>
        <p>Sign in to manage shipments, or track a shipment by number below.</p>
    </NotAuthorized>
</AuthorizeView>

<hr />

<h3>Track a Shipment</h3>
<div class="d-flex gap-2 mb-3">
    <input class="form-control" style="max-width: 300px;" placeholder="Enter tracking number" @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
    <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">No shipment found for "<strong>@searchedNumber</strong>".</div>
}
else if (shipment is not null)
{
    <div class="card" style="max-width: 500px;">
        <div class="card-body">
            <h5 class="card-title">@shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> <span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></p>
            <p><strong>From:</strong> @shipment.Origin</p>
            <p><strong>To:</strong> @shipment.Destination</p>
            <p><strong>Description:</strong> @shipment.Description</p>
            @if (shipment.EstimatedDelivery.HasValue)
            {
                <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</p>
            }
        </div>
    </div>
}

