@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<Shipment>? shipments;
    private string filter = string.Empty;
    private string statusFilter = string.Empty;
    private Shipment newShipment = new();
    private DateTime? newEstimatedDelivery;
    private bool creating;
    private string? createMessage;

    private IEnumerable<Shipment> FilteredShipments => shipments?.Where(s =>
        (string.IsNullOrEmpty(filter) || s.Destination.Contains(filter, StringComparison.OrdinalIgnoreCase)) &&
        (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
    ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private void ClearFilters()
    {
        filter = string.Empty;
        statusFilter = string.Empty;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber) || string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createMessage = "Tracking number and destination are required.";
            return;
        }

        creating = true;
        createMessage = null;
        newShipment.EstimatedDelivery = newEstimatedDelivery;
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Add(created);
        createMessage = $"Shipment {created.TrackingNumber} created successfully.";
        newShipment = new();
        newEstimatedDelivery = null;
        creating = false;
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

