@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize]

<PageTitle>My Shipments</PageTitle>

<h2>My Shipments</h2>

@if (string.IsNullOrEmpty(userEmail))
{
    <p><em>Loading...</em></p>
}
else if (shipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found for your account (<strong>@userEmail</strong>).</div>
}
else
{
    <div class="mb-3">
        <input class="form-control" style="max-width: 300px;" placeholder="Filter by tracking # or destination..." @bind="filter" @bind:event="oninput" />
    </div>

    <div class="row">
        @foreach (var s in FilteredShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@s.TrackingNumber</strong>
                        <span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1"><strong>Description:</strong> @s.Description</p>
                        @if (s.EstimatedDelivery.HasValue)
                        {
                            <p class="mb-0">
                                <strong>Estimated Delivery:</strong>
                                <span class="@(s.EstimatedDelivery.Value < DateTime.UtcNow && s.Status != ShipmentStatus.Delivered ? "text-danger fw-bold" : "")">
                                    @s.EstimatedDelivery.Value.ToString("MMM dd, yyyy")
                                </span>
                            </p>
                        }
                    </div>
                    <div class="card-footer text-muted">
                        Created @s.CreatedAt.ToString("MMM dd, yyyy")
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
    [CascadingParameter] private Task<AuthenticationState> AuthStateTask { get; set; } = default!;

    private List<Shipment>? shipments;
    private string? userEmail;
    private string filter = string.Empty;

    private IEnumerable<Shipment> FilteredShipments => shipments?.Where(s =>
        string.IsNullOrEmpty(filter) ||
        s.TrackingNumber.Contains(filter, StringComparison.OrdinalIgnoreCase) ||
        s.Destination.Contains(filter, StringComparison.OrdinalIgnoreCase)
    ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateTask;
        userEmail = authState.User.Identity?.Name;
        if (!string.IsNullOrEmpty(userEmail))
        {
            shipments = await ShipmentService.GetShipmentsForCustomerAsync(userEmail);
        }
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

